import java.util.*;class Solution{public boolean containsNearbyAlmostDuplicate(int[]a,int k,int t){if(t<0)return false;long w=(long)t+1;Map<Long,Long>m=new HashMap<>();for(int i=0;i<a.length;i++){long x=a[i],b=x>=0?x/w:(x+1)/w-1;if(m.containsKey(b)||m.containsKey(b-1)&&Math.abs(x-m.get(b-1))<=t||m.containsKey(b+1)&&Math.abs(x-m.get(b+1))<=t)return true;m.put(b,x);if(i>=k){long y=a[i-k],id=y>=0?y/w:(y+1)/w-1;m.remove(id);}}return false;}}
